toolArgs.file_text:
@using sv_aadb180b8ace4eb98001d1da8611c312.Services
@inject ISettingsService SettingsService

@if (_loading)
{
    <div class="text-center py-4"><div class="spinner-border" role="status"></div></div>
}
else
{
    <h4 class="mb-4">Appearance Settings</h4>

    @if (!string.IsNullOrEmpty(_message))
    {
        <div class="alert alert-success alert-dismissible fade show" role="alert">
            @_message
            <button type="button" class="btn-close" @onclick="() => _message = null"></button>
        </div>
    }

    <div class="row">
        <div class="col-md-7">
            <!-- Theme -->
            <div class="mb-4">
                <h6 class="fw-semibold">Theme</h6>
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                               value="@theme" checked="@(_theme == theme)"
                               @onchange="() => _theme = theme" />
                        <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                    </div>
                }
            </div>

            <!-- Font Size -->
            <div class="mb-4">
                <h6 class="fw-semibold">Font Size</h6>
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
                               value="@size" checked="@(_fontSize == size)"
                               @onchange="() => _fontSize = size" />
                        <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                    </div>
                }
            </div>

            <!-- Language -->
            <div class="mb-4">
                <h6 class="fw-semibold">Language</h6>
                <select class="form-select" style="max-width:250px;" @bind="_language">
                    @foreach (var lang in _languages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="mb-4">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                    <label class="form-check-label" for="compactMode">Compact Mode</label>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Save
            </button>
        </div>

        <!-- Live Preview -->
        <div class="col-md-5">
            <h6 class="fw-semibold mb-3">Live Preview</h6>
            <div class="border rounded @PreviewBgClass" style="@PreviewStyle">
                <div class="@PreviewPadding">
                    <div class="d-flex align-items-center mb-2">
                        <div class="rounded-circle me-2 @PreviewAccentBg" style="width:32px;height:32px;"></div>
                        <div>
                            <div class="fw-bold" style="@PreviewTextColor">Jane Doe</div>
                            <small style="@PreviewMutedColor">jane@example.com</small>
                        </div>
                    </div>
                    <hr style="@PreviewBorderColor" />
                    <p style="@PreviewTextColor" class="mb-2">
                        This is how your content will look with the selected settings.
                    </p>
                    <button class="btn btn-sm @PreviewButtonClass">Sample Button</button>
                </div>
            </div>
            <small class="text-muted d-block mt-2">
                Theme: @_theme · Font: @_fontSize · Compact: @(_compactMode ? "On" : "Off")
            </small>
        </div>
    </div>
}

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _message;
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private static readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese"];

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        await SettingsService.SaveAppearanceAsync(new AppearanceSettings(_theme, _fontSize, _language, _compactMode));
        _message = "Appearance settings saved!";
        _saving = false;
    }

    private string PreviewStyle => $"font-size:{FontSizePx}; min-height:180px;";
    private string FontSizePx => _fontSize switch { "Small" => "12px", "Large" => "18px", _ => "14px" };
    private string PreviewPadding => _compactMode ? "p-2" : "p-3";
    private bool IsDark => _theme == "Dark";
